CREATE DATABASE IF NOT EXISTS ocean_restaurant CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE ocean_restaurant;

-- #####################  CẤU TRÚC BẢNG  #####################

CREATE TABLE IF NOT EXISTS categories (
    category_id     VARCHAR(20)  NOT NULL,
    name            VARCHAR(100) NOT NULL,
    active          TINYINT(1)   NOT NULL DEFAULT 1,
    PRIMARY KEY (category_id),
    UNIQUE KEY uq_categories_name (name)
);

CREATE TABLE IF NOT EXISTS items (
    item_id         VARCHAR(20)   NOT NULL,
    name            VARCHAR(150)  NOT NULL,
    price           DECIMAL(15,2) NOT NULL,
    category_id     VARCHAR(20)   NOT NULL,
    status          VARCHAR(30)   NOT NULL DEFAULT 'Đang bán',
    PRIMARY KEY (item_id),
    CONSTRAINT fk_items_category FOREIGN KEY (category_id) REFERENCES categories (category_id)
);

CREATE TABLE IF NOT EXISTS ingredients (
    ingredient_id   VARCHAR(20)   NOT NULL,
    name            VARCHAR(100)  NOT NULL,
    unit            VARCHAR(20)   NOT NULL,
    quantity        DECIMAL(14,4) NOT NULL DEFAULT 0,
    min_quantity    DECIMAL(14,4) NOT NULL DEFAULT 0,
    expiry_date     DATE          NULL,
    PRIMARY KEY (ingredient_id),
    UNIQUE KEY uq_ingredients_name (name)
);

CREATE TABLE IF NOT EXISTS recipes (
    recipe_id       VARCHAR(20)   NOT NULL,
    item_id         VARCHAR(20)   NOT NULL,
    ingredient_id   VARCHAR(20)   NOT NULL,
    quantity        DECIMAL(14,4) NOT NULL,
    PRIMARY KEY (recipe_id),
    UNIQUE KEY uq_recipes_item_ingredient (item_id, ingredient_id),
    CONSTRAINT fk_recipes_item       FOREIGN KEY (item_id)       REFERENCES items (item_id) ON DELETE CASCADE,
    CONSTRAINT fk_recipes_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients (ingredient_id) ON DELETE RESTRICT
);

CREATE TABLE IF NOT EXISTS promotions (
    promotion_id    VARCHAR(20)   NOT NULL,
    name            VARCHAR(150)  NOT NULL,
    discount        DECIMAL(5,2)  NOT NULL,
    start_date      DATE          NOT NULL,
    end_date        DATE          NOT NULL,
    item_id         VARCHAR(20)   NULL,
    apply_type      VARCHAR(10)   NOT NULL DEFAULT 'order',
    min_order_value DECIMAL(15,2) NOT NULL DEFAULT 0,
    PRIMARY KEY (promotion_id),
    CONSTRAINT fk_promotions_item FOREIGN KEY (item_id) REFERENCES items (item_id) ON DELETE CASCADE
);

CREATE TABLE IF NOT EXISTS member_tiers (
    member_tier_id   VARCHAR(20)   NOT NULL,
    tier_name        VARCHAR(50)   NOT NULL,
    min_total_spent  DECIMAL(15,2) NOT NULL,
    max_total_spent  DECIMAL(15,2) NULL,
    discount_percent DECIMAL(5,2)  NOT NULL,
    description      VARCHAR(255)  NULL,
    PRIMARY KEY (member_tier_id),
    UNIQUE KEY uq_member_tiers_name (tier_name),
    CONSTRAINT chk_member_tiers_discount CHECK (discount_percent >= 0 AND discount_percent <= 100)
);

CREATE TABLE IF NOT EXISTS customers (
    customer_id     VARCHAR(20)   NOT NULL,
    full_name       VARCHAR(100)  NOT NULL,
    phone           VARCHAR(20)   NOT NULL,
    created_at      DATETIME      NOT NULL,
    total_spent     DECIMAL(15,2) NOT NULL DEFAULT 0,
    total_orders    INT           NOT NULL DEFAULT 0,
    member_tier_id  VARCHAR(20)   NOT NULL DEFAULT 'HT01',
    active          TINYINT(1)    NOT NULL DEFAULT 1,
    PRIMARY KEY (customer_id),
    UNIQUE KEY uq_customers_phone (phone),
    CONSTRAINT fk_customers_member_tier FOREIGN KEY (member_tier_id) REFERENCES member_tiers (member_tier_id)
);

CREATE TABLE IF NOT EXISTS users (
    user_id         VARCHAR(20)  NOT NULL,
    username        VARCHAR(50)  NOT NULL,
    password_hash   VARCHAR(255) NOT NULL,
    full_name       VARCHAR(100) NOT NULL,
    role            VARCHAR(20)  NOT NULL DEFAULT 'cashier',
    active          TINYINT(1)   NOT NULL DEFAULT 1,
    created_at      DATETIME     NOT NULL,
    PRIMARY KEY (user_id),
    UNIQUE KEY uq_users_username (username)
);

CREATE TABLE IF NOT EXISTS orders (
    order_id         VARCHAR(20)   NOT NULL,
    customer_name    VARCHAR(100)  NOT NULL,
    customer_id      VARCHAR(20)   NULL,
    order_date       DATETIME      NOT NULL,
    status           VARCHAR(30)   NOT NULL DEFAULT 'Chờ xác nhận',
    total            DECIMAL(15,2) NOT NULL DEFAULT 0,
    discount_amount  DECIMAL(15,2) NOT NULL DEFAULT 0,
    final_total      DECIMAL(15,2) NOT NULL DEFAULT 0,
    promotion_id     VARCHAR(20)   NULL,
    table_number     VARCHAR(30)   NULL,
    special_request  VARCHAR(500)  NULL,
    member_discount  DECIMAL(15,2) NOT NULL DEFAULT 0,
    member_tier_name VARCHAR(50)   NULL,
    member_accounted TINYINT(1)    NOT NULL DEFAULT 0,
    confirmed_at     DATETIME      NULL,
    canceled_at      DATETIME      NULL,
    stock_deducted   TINYINT(1)    NOT NULL DEFAULT 0,
    PRIMARY KEY (order_id),
    KEY idx_orders_order_date (order_date),
    KEY idx_orders_status (status),
    CONSTRAINT fk_orders_customer  FOREIGN KEY (customer_id)  REFERENCES customers (customer_id),
    CONSTRAINT fk_orders_promotion FOREIGN KEY (promotion_id) REFERENCES promotions (promotion_id)
);

CREATE TABLE IF NOT EXISTS order_details (
    order_detail_id   VARCHAR(20)   NOT NULL,
    order_id          VARCHAR(20)   NOT NULL,
    item_id           VARCHAR(20)   NOT NULL,
    quantity          INT           NOT NULL,
    price             DECIMAL(15,2) NOT NULL,
    item_discount     DECIMAL(15,2) NOT NULL DEFAULT 0,
    ordered_at        DATETIME      NULL,
    canceled_quantity INT           NOT NULL DEFAULT 0,
    kitchen_ack       TINYINT(1)    NOT NULL DEFAULT 1,
    PRIMARY KEY (order_detail_id),
    CONSTRAINT fk_order_details_order FOREIGN KEY (order_id) REFERENCES orders (order_id) ON DELETE CASCADE,
    CONSTRAINT fk_order_details_item  FOREIGN KEY (item_id)  REFERENCES items (item_id)
);

CREATE TABLE IF NOT EXISTS inventory_movements (
    movement_id     INT           NOT NULL AUTO_INCREMENT,
    ingredient_id   VARCHAR(20)   NOT NULL,
    movement_type   VARCHAR(20)   NOT NULL,
    quantity        DECIMAL(14,4) NOT NULL,
    before_quantity DECIMAL(14,4) NOT NULL,
    after_quantity  DECIMAL(14,4) NOT NULL,
    note            VARCHAR(255)  NULL,
    created_at      DATETIME      NOT NULL,
    PRIMARY KEY (movement_id),
    CONSTRAINT fk_movements_ingredient FOREIGN KEY (ingredient_id) REFERENCES ingredients (ingredient_id)
);


-- #####################  DỮ LIỆU  #####################

-- ---- Danh mục món (categories) : 9 dòng ----
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    active = VALUES(active);

-- ---- Món ăn (items) : 81 dòng ----
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    price = VALUES(price),
    category_id = VALUES(category_id),
    status = VALUES(status);

-- ---- Nguyên liệu (tồn kho) (ingredients) : 20 dòng ----
-- Hạn sử dụng được thiết lập theo mốc dữ liệu 12/11/2026 (định dạng YYYY-MM-DD).
-- Phân bố gồm nguyên liệu đã hết hạn, sắp hết hạn, còn hạn trung bình và hạn dài.
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    unit = VALUES(unit),
    quantity = VALUES(quantity),
    min_quantity = VALUES(min_quantity),
    expiry_date = VALUES(expiry_date);

-- ---- Công thức: món <-> nguyên liệu (recipes) : 346 dòng ----
ON DUPLICATE KEY UPDATE
    item_id = VALUES(item_id),
    ingredient_id = VALUES(ingredient_id),
    quantity = VALUES(quantity);

-- ---- Khuyến mại (promotions) : 41 dòng ----
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    discount = VALUES(discount),
    start_date = VALUES(start_date),
    end_date = VALUES(end_date),
    item_id = VALUES(item_id),
    apply_type = VALUES(apply_type),
    min_order_value = VALUES(min_order_value);

-- ---- Hạng thành viên (member_tiers) : 3 dòng ----
ON DUPLICATE KEY UPDATE
    tier_name = VALUES(tier_name),
    min_total_spent = VALUES(min_total_spent),
    max_total_spent = VALUES(max_total_spent),
    discount_percent = VALUES(discount_percent),
    description = VALUES(description);

-- ---- Khách hàng thành viên (customers) : 18 dòng ----
ON DUPLICATE KEY UPDATE
    full_name = VALUES(full_name),
    phone = VALUES(phone),
    created_at = VALUES(created_at),
    total_orders = VALUES(total_orders),
    total_spent = VALUES(total_spent),
    member_tier_id = VALUES(member_tier_id),
    active = VALUES(active);

-- ---- Tài khoản nhân viên (users) : 6 dòng ----
ON DUPLICATE KEY UPDATE
    username = VALUES(username),
    password_hash = VALUES(password_hash),
    full_name = VALUES(full_name),
    role = VALUES(role),
    active = VALUES(active),
    created_at = VALUES(created_at);

-- ---- Đơn hàng (orders) : 36 dòng ----
ON DUPLICATE KEY UPDATE
    customer_name = VALUES(customer_name),
    customer_id = VALUES(customer_id),
    order_date = VALUES(order_date),
    status = VALUES(status),
    total = VALUES(total),
    discount_amount = VALUES(discount_amount),
    final_total = VALUES(final_total),
    promotion_id = VALUES(promotion_id),
    confirmed_at = VALUES(confirmed_at),
    canceled_at = VALUES(canceled_at),
    stock_deducted = VALUES(stock_deducted);

-- ---- Chi tiết đơn hàng (mỗi dòng = 1 món trong đơn) (order_details) : 229 dòng ----
ON DUPLICATE KEY UPDATE
    order_id = VALUES(order_id),
    item_id = VALUES(item_id),
    quantity = VALUES(quantity),
    price = VALUES(price),
    item_discount = VALUES(item_discount),
    ordered_at = VALUES(ordered_at);

-- #####################  ĐƠN HÀNG MẪU BỔ SUNG 12/09/2026 - 11/11/2026  #####################
-- 20-30 đơn/ngày; mỗi đơn 1.000.000-2.000.000 VND; giá theo bảng items.
-- Khách vãng lai, không giảm giá, không thay đổi số liệu thành viên.
-- Đơn lịch sử đã hoàn thành, stock_deducted = 1; tồn kho hiện tại là số dư chốt, không trừ lại.
-- Giữ nguyên toàn bộ cấu trúc và dữ liệu ban đầu; chạy lại cập nhật cùng mã, không tạo bản sao.

ON DUPLICATE KEY UPDATE
    customer_name = VALUES(customer_name),
    customer_id = VALUES(customer_id),
    order_date = VALUES(order_date),
    status = VALUES(status),
    total = VALUES(total),
    discount_amount = VALUES(discount_amount),
    final_total = VALUES(final_total),
    promotion_id = VALUES(promotion_id),
    confirmed_at = VALUES(confirmed_at),
    canceled_at = VALUES(canceled_at),
    stock_deducted = VALUES(stock_deducted);

ON DUPLICATE KEY UPDATE
    order_id = VALUES(order_id),
    item_id = VALUES(item_id),
    quantity = VALUES(quantity),
    price = VALUES(price),
    item_discount = VALUES(item_discount),
    ordered_at = VALUES(ordered_at);

-- ===============================================================
-- DU LIEU BO SUNG OCEAN RESTAURANT - MOC 13/11/2026
-- Chi bo sung customers/orders/order_details; khong sua bang khac.
-- INSERT IGNORE dam bao co the chay lai ma khong tao ban ghi trung.
-- ===============================================================

-- 1. Them 200 khach hang thanh vien moi (KH019-KH218).

-- 2. Them cac don hang con thieu tu 02/01/2026 den 11/09/2026 va 12-13/11/2026.
-- Don moi co tong tien 500.000-3.000.000 VND; tong = SUM(so_luong * don_gia).
-- Don moi khong gan khuyen mai, khong giam gia; final_total = total.
-- stock_deducted=1 voi don hoan thanh de phan anh giao dich lich su; khong cap nhat ton kho.

-- 3. Them chi tiet mon an tuong ung voi tung don hang.
-- Don gia lay truc tiep tu items; item_discount=0.

-- 4. Dong bo so don va tong chi tieu: chi tinh don Da hoan thanh.
-- Khong tinh don Da huy / Cho xac nhan; khong thay doi khach hang goc ngoai cac chi so tich luy.
UPDATE customers c
LEFT JOIN (
    SELECT customer_id,
           COUNT(*) AS completed_orders,
           COALESCE(SUM(final_total), 0) AS completed_spent
    FROM orders
    WHERE status = 'Đã hoàn thành'
      AND customer_id IS NOT NULL
    GROUP BY customer_id
) x ON x.customer_id = c.customer_id
SET c.total_orders = COALESCE(x.completed_orders, 0),
    c.total_spent = COALESCE(x.completed_spent, 0),
    c.member_tier_id = CASE
        WHEN COALESCE(x.completed_spent, 0) >= 35000000 THEN 'HT03'
        WHEN COALESCE(x.completed_spent, 0) >= 25000000 THEN 'HT02'
        ELSE 'HT01'
    END;


-- ===============================================================
-- 5. BAO CAO THONG KE VA KIEM TRA TINH NHAT QUAN
-- ===============================================================

-- 5.1. So luong don hang theo nam va trang thai
SELECT YEAR(order_date) AS nam, status AS trang_thai, COUNT(*) AS so_don
FROM orders
GROUP BY YEAR(order_date), status
ORDER BY nam, status;

-- 5.2. Tong so khach hang thanh vien
SELECT COUNT(*) AS tong_khach_hang_thanh_vien
FROM customers;

-- 5.3. So luong khach hang theo hang thanh vien
SELECT mt.tier_name AS hang_thanh_vien, COUNT(c.customer_id) AS so_khach_hang
FROM member_tiers mt
LEFT JOIN customers c ON c.member_tier_id = mt.member_tier_id
GROUP BY mt.member_tier_id, mt.tier_name
ORDER BY mt.min_total_spent;

-- 5.4. Tong chi tieu va so don hoan thanh cua tung khach hang
SELECT c.customer_id, c.full_name, c.total_orders, c.total_spent,
       mt.tier_name AS hang_thanh_vien
FROM customers c
JOIN member_tiers mt ON mt.member_tier_id = c.member_tier_id
ORDER BY c.total_spent DESC, c.customer_id;

-- 5.5. Kiem tra don hang khong co chi tiet
SELECT COUNT(*) AS don_hang_khong_co_chi_tiet
FROM orders o
LEFT JOIN order_details od ON od.order_id = o.order_id
WHERE od.order_detail_id IS NULL;

-- 5.6. Kiem tra tong tien truoc giam gia co khop SUM(so_luong * don_gia)
SELECT COUNT(*) AS so_don_lech_tong_tien_goc
FROM (
    SELECT o.order_id
    FROM orders o
    LEFT JOIN order_details od ON od.order_id = o.order_id
    GROUP BY o.order_id, o.total
    HAVING ABS(o.total - COALESCE(SUM(od.quantity * od.price), 0)) > 0.01
) mismatch;

-- 5.7. Kiem tra thanh toan: final_total = total - discount_amount
SELECT COUNT(*) AS so_don_lech_thanh_toan
FROM orders
WHERE ABS(final_total - (total - discount_amount)) > 0.01;

-- 5.8. Kiem tra don hang lien ket customer_id khong ton tai
SELECT COUNT(*) AS don_hang_co_customer_khong_hop_le
FROM orders o
LEFT JOIN customers c ON c.customer_id = o.customer_id
WHERE o.customer_id IS NOT NULL AND c.customer_id IS NULL;

-- 5.9. Kiem tra thong ke customer co khop lich su don hoan thanh
SELECT COUNT(*) AS so_khach_hang_lech_thong_ke
FROM customers c
LEFT JOIN (
    SELECT customer_id, COUNT(*) AS cnt, SUM(final_total) AS spent
    FROM orders
    WHERE status = 'Đã hoàn thành' AND customer_id IS NOT NULL
    GROUP BY customer_id
) x ON x.customer_id = c.customer_id
WHERE c.total_orders <> COALESCE(x.cnt, 0)
   OR ABS(c.total_spent - COALESCE(x.spent, 0)) > 0.01;

-- 5.10. Kiem tra hang thanh vien co phu hop tong chi tieu
SELECT COUNT(*) AS so_khach_hang_sai_hang
FROM customers c
WHERE (c.total_spent >= 35000000 AND c.member_tier_id <> 'HT03')
   OR (c.total_spent >= 25000000 AND c.total_spent < 35000000 AND c.member_tier_id <> 'HT02')
   OR (c.total_spent < 25000000 AND c.member_tier_id <> 'HT01');
